referenceSolutions.javascript:
export function solve(calls) {
  const cache = new Map();
  let evaluations = 0;
  const values = calls.map((x) => {
    if (!cache.has(x)) {
      cache.set(x, x * x);
      evaluations++;
    }
    return cache.get(x);
  });
  return { values, evaluations };
}

referenceSolutions.typescript:
export function solve(calls: number[]): any {
  const cache = new Map<number, number>();
  let evaluations = 0;
  const values = calls.map((x) => {
    if (!cache.has(x)) {
      cache.set(x, x * x);
      evaluations++;
    }
    return cache.get(x)!;
  });
  return { values, evaluations };
}
